  AND EXISTS (SELECT 1 FROM TraitModifiers WHERE TraitType = 'TRAIT_CIVILIZATION_PLATOS_REPUBLIC' AND ModifierId = 'TRAIT_WILDCARD_GOVERNMENT_SLOT');

